# Build ILP for optimal scheduling
# Variables: one binary var per (target, pair_index)
# Constraints:
#   - At most one pair per target
#   - No satellite conflicts between selected pairs' observations
# Objective: maximize coverage (big bonus) + quality

pair_list = []  # (pair_idx, tid, c1, c2, score, conv)
for tid in target_pairs:
    for pi, (c1, c2, score, conv) in enumerate(target_pairs[tid][:20]):
        pair_list.append((len(pair_list), tid, c1, c2, score, conv))

print(f"  ILP: {len(pair_list)} pair candidates")

# Extract observations per pair
pair_obs = []
for idx, tid, c1, c2, score, conv in pair_list:
    obs1 = {
        'sid': c1['sid'],
        'start': c1['midpoint_offset'] - HALF_DUR,
        'end': c1['midpoint_offset'] + HALF_DUR,
        'boresight': boresight_vector(c1['along_deg'], c1['across_deg'],
                                      c1['nadir_hat'], c1['along_hat'], c1['cross_hat']),
    }
    obs2 = {
        'sid': c2['sid'],
        'start': c2['midpoint_offset'] - HALF_DUR,
        'end': c2['midpoint_offset'] + HALF_DUR,
        'boresight': boresight_vector(c2['along_deg'], c2['across_deg'],
                                      c2['nadir_hat'], c2['along_hat'], c2['cross_hat']),
    }
    pair_obs.append((obs1, obs2))

def obs_conflict(o1, o2):
    if o1['sid'] != o2['sid']:
        return False
    sd = sat_lookup[o1['sid']]
    if o1['start'] < o2['end'] and o1['end'] > o2['start']:
        return True
    cos_a = np.clip(np.dot(o1['boresight'], o2['boresight']), -1, 1)
    theta = np.degrees(np.arccos(cos_a))
    gap_needed = compute_slew_time(theta, sd['max_slew_velocity_deg_per_s'],
                                   sd['max_slew_acceleration_deg_per_s2'],
                                   sd['settling_time_s']) + SLEW_BUFFER
    if o1['end'] <= o2['start']:
        return o2['start'] - o1['end'] < gap_needed
    elif o2['end'] <= o1['start']:
        return o1['start'] - o2['end'] < gap_needed
    return True

# Find conflicts between pairs
# Group by satellite for efficient conflict detection
sat_pair_obs = {}
for pi in range(len(pair_list)):
    for obs in pair_obs[pi]:
        sat_pair_obs.setdefault(obs['sid'], []).append((pi, obs))

conflicts = set()
for sid, obs_list in sat_pair_obs.items():
    obs_list.sort(key=lambda x: x[1]['start'])
    for i in range(len(obs_list)):
        pi, oi = obs_list[i]
        for j in range(i + 1, len(obs_list)):
            pj, oj = obs_list[j]
            if pi == pj:
                continue
            if oj['start'] - oi['end'] > 120:
                break
            if obs_conflict(oi, oj):
                conflicts.add((min(pi, pj), max(pi, pj)))

print(f"  ILP: {len(conflicts)} conflict constraints")

# Build model
prob = pulp.LpProblem("stereo_schedule", pulp.LpMaximize)
x = [pulp.LpVariable(f"x_{i}", cat='Binary') for i in range(len(pair_list))]

# Objective: maximize coverage (10 per target) + quality (score per pair)
prob += pulp.lpSum(10 * x[i] + pair_list[i][4] * x[i] for i in range(len(pair_list)))

# At most one pair per target
by_target = {}
for i, (_, tid, _, _, _, _) in enumerate(pair_list):
    by_target.setdefault(tid, []).append(i)
for tid, indices in by_target.items():
    prob += pulp.lpSum(x[i] for i in indices) <= 1

# No conflicts
for pi, pj in conflicts:
    prob += x[pi] + x[pj] <= 1

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=0, timeLimit=60))

scheduled_targets = {}
sat_schedules = {sid: [] for sid in satellites}
for i in range(len(pair_list)):
    if x[i].value() and x[i].value() > 0.5:
        _, tid, c1, c2, score, conv = pair_list[i]
        s1, e1 = c1['midpoint_offset'] - HALF_DUR, c1['midpoint_offset'] + HALF_DUR
        s2, e2 = c2['midpoint_offset'] - HALF_DUR, c2['midpoint_offset'] + HALF_DUR
        add_obs(c1['sid'], s1, e1, c1['along_deg'], c1['across_deg'],
               c1['nadir_hat'], c1['along_hat'], c1['cross_hat'])
        add_obs(c2['sid'], s2, e2, c2['along_deg'], c2['across_deg'],
               c2['nadir_hat'], c2['along_hat'], c2['cross_hat'])
        scheduled_targets[tid] = [
            make_action(c1, tid, horizon_start, HALF_DUR),
            make_action(c2, tid, horizon_start, HALF_DUR),
        ]

